mapper.select:
SELECT SDT.ID,SDT.TEMPLATE_NAME,SDT.PARK_ID,PARK.PARK_NAME,SDT.JCHENID,SDT.JCHENNAME
FROM SMT_SD_TEMPLATES SDT
INNER JOIN SMT_PARK PARK
ON SDT.PARK_ID=PARK.ID


		AND SDT.PARK_ID=#{query.parkId}



		AND SDT.TEMPLATE_NAME=#{query.templateName}



		AND SDT.JCHENID=#{query.jchenid}



		and SDT.PARK_ID in

			#{item}




ORDER BY SDT.ID

select staff.BADGE,sdr.CATEGORY_ID,sdr.STANDARD_QTY,sdr.OVER_FEE from SMT_SD_TEMPLATES sdt join SMT_TEMPLATES_RULE sdr on sdt.ID=sdr.TEMP_ID join SMT_STAFF staff on staff.JCHE_ID=sdt.JCHENID where staff.BADGE in
#{item}
and sdr.MONTH_NUM=#{monthNum} and sdr.CATEGORY_ID=#{categoryId}
